# -*- coding: utf-8 -*-
"""读取教材数据，生成同目录的离线交互HTML；依赖 openpyxl。"""
from pathlib import Path
import json
import warnings
import openpyxl

HERE=Path(__file__).resolve().parent
SOURCE=next((p for base in HERE.parents for p in base.glob('《*/第三章*.xlsm')),None)
if SOURCE is None:
    raise FileNotFoundError('未找到教材目录中的第三章 动态图表.xlsm')
# 只读原始数据，绝不保存或修改带宏的工作簿。
with warnings.catch_warnings():
    warnings.filterwarnings('ignore',message='Slicer List extension is not supported.*')
    book=openpyxl.load_workbook(SOURCE,data_only=True,read_only=True)
sheet=book['7 动态滑珠图']
def row(r,c1,c2):
    values=[sheet.cell(r,c).value for c in range(c1,c2+1)]
    if any(v is None for v in values):raise ValueError(f'数据缺失：{sheet.title}第{r}行')
    return values
def col(c,r1,r2):
    values=[sheet.cell(r,c).value for r in range(r1,r2+1)]
    if any(v is None for v in values):raise ValueError(f'数据缺失：{sheet.title}第{c}列')
    return values
regions=col(2,3,8);months=row(2,3,8)
data={'labels':regions,'months':months,'matrix':[row(r,3,8) for r in range(3,9)],'initialMode':'month' if sheet['K2'].value==1 else 'region','initialIndex':int(sheet['K3'].value)-1}
assert data['matrix'][-1]==[.32,.49,.65,.73,.536,.7468]
assert all(0<=v<=1 for values in data['matrix'] for v in values)

book.close()

PAGE = '<!doctype html>\n<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>动态滑珠图</title><style>\n:root{color-scheme:dark;--bg:#1a1e43;--ink:#f5f5fa;--muted:#d1d4e8;--blue:#0070c0;--edge:#5e6384;--focus:#f5c353}\n*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--ink);font-family:"Microsoft YaHei","SimHei",sans-serif}body{font-variant-numeric:tabular-nums}::selection{background:#0070c0;color:white}\nmain{max-width:1000px;margin:0 auto;padding:44px 0 24px}h1{font-size:34px;line-height:1.4;margin:0 55px;font-weight:700;letter-spacing:0}button,select,input{font:inherit}button,select{min-height:36px;border:1px solid #a4a6b4;border-radius:2px;padding:5px 13px;background:#f2f2f4;color:#171a31;cursor:pointer}button:hover,select:hover{background:#fff}button[aria-pressed="true"]{background:#0070c0;border-color:#4bb5f4;color:white}button:disabled{opacity:.45;cursor:default}input{accent-color:#0070c0}button:focus-visible,select:focus-visible,input:focus-visible,[tabindex]:focus-visible{outline:3px solid var(--focus);outline-offset:4px}\n.toolbar{display:flex;justify-content:flex-end;align-items:center;gap:12px;flex-wrap:wrap;margin:14px 55px 4px;min-height:40px}.toolbar label{display:inline-flex;gap:7px;align-items:center;font-size:16px;cursor:pointer}.toolbar input{width:16px;height:16px;margin:0}.toolbar fieldset{display:flex;gap:14px;border:0;padding:0;margin:0}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}\n.legend-toolbar{justify-content:flex-start;gap:24px}.legend-toolbar label{padding:7px 12px;font-size:16px;color:white}.legend-toolbar label:nth-of-type(1){background:#0070c0}.legend-toolbar label:nth-of-type(2){background:#e74e69}.legend-toolbar label:nth-of-type(3){background:#ffc000;color:#182040}\n.plot-wrap{width:100%;overflow-x:auto;scrollbar-color:#737aab #1a1e43;scrollbar-width:thin}.plot{display:block;width:100%;height:auto;touch-action:pan-x pan-y}.plot text{font-family:"Microsoft YaHei","SimHei",sans-serif;fill:var(--ink)}.mark{cursor:default;transition:filter .15s}.mark:hover,.mark:focus{filter:brightness(1.12)}.grid{stroke:#b7bed2;stroke-opacity:.20;stroke-width:1;stroke-dasharray:9 5}.axis{stroke:#5e6384;stroke-width:1}\nfooter{font-size:13px;color:var(--muted);margin:15px 50px 0;line-height:1.7}#tip{position:fixed;z-index:5;max-width:300px;padding:10px 13px;background:#f7f8fc;color:#172039;border:1px solid #9ba6cb;border-radius:4px;box-shadow:0 5px 18px #0005;font-size:14px;line-height:1.6;pointer-events:none;white-space:pre-line}#tip[hidden]{display:none}\n.slicer{margin:0 55px 26px;border:1px solid #5e6384;padding:12px;background:#f1f2f7;color:#202439}.slicer-top{display:flex;align-items:center;gap:18px;justify-content:space-between;margin-bottom:12px}.slicer-top label{display:flex;align-items:center;gap:6px;font-size:14px}.slicer-top button{min-height:30px;font-size:13px}.departments{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.departments button{min-height:35px;font-size:15px;text-align:left}.slicer button[aria-pressed="false"]{background:#dce8f7;border-color:#92b4d7;color:#1c3553}.slicer button[aria-pressed="false"]:hover{background:#c7def8}.selection{font-size:14px;color:var(--muted);margin:8px 55px 0;min-height:20px}\n@media(max-width:640px){main{padding-top:24px}h1{font-size:25px;margin:0 22px}.toolbar{margin:16px 22px 5px;gap:9px}.toolbar label{font-size:14px}.legend-toolbar{gap:8px}.legend-toolbar label{padding:6px 8px;font-size:14px}footer{margin:15px 22px;font-size:12px}.slicer{margin:0 22px 20px}.slicer-top{gap:7px;flex-wrap:wrap}.departments{grid-template-columns:repeat(2,1fr)}.selection{margin:8px 22px}.slicer-top strong{margin-right:auto}}\n@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n</style></head>\n<body><main><h1 id="chart-title">2022年上半年区域销量目标达成率情况</h1><div class="toolbar"><fieldset><legend class="sr-only">筛选方式</legend><label><input type="radio" name="mode" value="region">区域</label><label><input type="radio" name="mode" value="month">月份</label></fieldset><select id="choice" aria-label="选择月份"></select></div>\n<div class="plot-wrap" tabindex="0" aria-label="图表区域"><svg id="chart" class="plot" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 510" role="group" aria-label="交互图表"></svg></div>\n<footer>*注：数据来源公司销售系统，日期截至2022.06.30</footer><p id="status" class="sr-only" aria-live="polite"></p></main>\n<div id="tip" role="tooltip" hidden></div><script id="source-data" type="application/json">__SOURCE_DATA__</script><script>\nconst DATA=JSON.parse(document.getElementById(\'source-data\').textContent);\nconst svg=document.getElementById(\'chart\'), title=document.getElementById(\'chart-title\'), status=document.getElementById(\'status\'), tip=document.getElementById(\'tip\');\nconst BG=\'#1a1e43\', BLUE=\'#0070c0\', PINK=\'#e74e69\', GOLD=\'#ffc000\';\nconst compact=()=>innerWidth<=640;\nfunction fit(){svg.setAttribute(\'viewBox\',`0 0 ${compact()?660:1000} 510`)}\nfit();addEventListener(\'resize\',()=>{fit();update()});\nconst esc=s=>String(s).replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst num=(v,d=0)=>Number(v).toLocaleString(\'en-US\',{useGrouping:false,minimumFractionDigits:d,maximumFractionDigits:d});\nconst pct=v=>num(v*100,0)+\'%\';\nconst exactPct=v=>Number((v*100).toFixed(2))+\'%\';\nfunction attrs(obj){return Object.entries(obj).map(([k,v])=>` ${k}="${esc(v)}"`).join(\'\')}\nfunction txt(x,y,s,size=19,anchor=\'middle\',fill=\'#f5f5fa\',more={}){return `<text${attrs({x,y,\'font-size\':size,\'text-anchor\':anchor,fill,...more})} style="fill:${fill}">${esc(s)}</text>`}\nfunction line(x1,y1,x2,y2,color,width=1,more={}){return `<line${attrs({x1,y1,x2,y2,stroke:color,\'stroke-width\':width,...more})}/>`}\nfunction rect(x,y,w,h,fill,more={}){return `<rect${attrs({x,y,width:w,height:Math.max(0,h),fill,...more})}/>`}\nfunction circle(x,y,r,fill,more={}){return `<circle${attrs({cx:x,cy:y,r,fill,...more})}/>`}\nfunction mark(label,value,extra={}){return {class:\'mark\',tabindex:0,role:\'img\',\'aria-label\':label,\'data-tip\':label,\'data-value\':value,...extra}}\nfunction polar(cx,cy,r,a){return [cx+r*Math.cos(a*Math.PI/180),cy+r*Math.sin(a*Math.PI/180)]}\nfunction ringPath(cx,cy,outer,inner,start,end){\n    const a=polar(cx,cy,outer,start),b=polar(cx,cy,outer,end),c=polar(cx,cy,inner,end),d=polar(cx,cy,inner,start),large=end-start>180?1:0;\n    return `M${a} A${outer},${outer} 0 ${large} 1 ${b} L${c} A${inner},${inner} 0 ${large} 0 ${d} Z`;\n}\nfunction ring(cx,cy,outer,inner,start,end,color,more={}){return `<path${attrs({d:ringPath(cx,cy,outer,inner,start,end),fill:color,...more})}/>`}\nfunction options(el,values,selected){el.innerHTML=values.map(s=>`<option${s===selected?\' selected\':\'\'}>${esc(s)}</option>`).join(\'\')}\nfunction announce(message){status.textContent=message;svg.setAttribute(\'aria-label\',message)}\nfunction defs(){return \'<defs><linearGradient id="bar-gradient" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#0070c0"/><stop offset="1" stop-color="#00b0f0"/></linearGradient></defs>\'}\nlet animation=0,shown=[];\nfunction animate(values,paint){\n    cancelAnimationFrame(animation);tip.hidden=true;\n    const from=shown.length===values.length?[...shown]:[...values];\n    const duration=matchMedia(\'(prefers-reduced-motion: reduce)\').matches?0:320;\n    const start=performance.now();\n    const frame=now=>{let t=duration?Math.min((now-start)/duration,1):1;let ease=1-Math.pow(1-t,3);shown=values.map((v,i)=>from[i]+(v-from[i])*ease);paint(shown,t===1);if(t<1)animation=requestAnimationFrame(frame)};\n    frame(start);\n}\nfunction showTip(el,x,y){\n    tip.textContent=el.dataset.tip;tip.hidden=false;\n    tip.style.left=Math.max(8,Math.min(x+14,innerWidth-tip.offsetWidth-12))+\'px\';\n    tip.style.top=Math.max(8,Math.min(y+12,innerHeight-tip.offsetHeight-12))+\'px\';\n}\nsvg.addEventListener(\'pointermove\',e=>{const el=e.target.closest(\'[data-tip]\');if(el)showTip(el,e.clientX,e.clientY);else tip.hidden=true});\nsvg.addEventListener(\'pointerleave\',()=>tip.hidden=true);\nsvg.addEventListener(\'focusin\',e=>{const el=e.target.closest(\'[data-tip]\');if(el){const b=el.getBoundingClientRect();showTip(el,b.x+b.width/2,b.y)}});\nsvg.addEventListener(\'focusout\',()=>tip.hidden=true);\ndocument.addEventListener(\'keydown\',e=>{if(e.key===\'Escape\')tip.hidden=true});\n\nconst modes=[...document.querySelectorAll(\'input[name="mode"]\')],select=document.getElementById(\'choice\');\nmodes.forEach(el=>el.checked=el.value===DATA.initialMode);\nconst remembered={month:DATA.months[DATA.initialMode===\'month\'?DATA.initialIndex:0],region:DATA.labels[DATA.initialMode===\'region\'?DATA.initialIndex:0]};\nfunction updateOptions(){const mode=modes.find(el=>el.checked).value;options(select,mode===\'month\'?DATA.months:DATA.labels,remembered[mode]);select.setAttribute(\'aria-label\',mode===\'month\'?\'选择月份\':\'选择区域\');update()}\nfunction update(){\n    const mode=modes.find(el=>el.checked).value,key=select.value;remembered[mode]=key;\n    let labels,values;\n    if(mode===\'month\'){const j=DATA.months.indexOf(key);labels=[...DATA.labels].reverse();values=DATA.matrix.map(row=>row[j]).reverse()}\n    else{const i=DATA.labels.indexOf(key);labels=[...DATA.months].reverse();values=[...DATA.matrix[i]].reverse()}\n    window.chartState={mode,choice:key,labels,values};announce(key+\'目标达成率：\'+labels.map((l,i)=>l+exactPct(values[i])).join(\'，\'));\n    animate(values,vs=>{\n        let s=\'\';vs.forEach((v,i)=>{const y=44+i*77,x0=compact()?95:130,length=compact()?510:765,x=x0+v*length;\n            s+=txt(x0-22,y+7,labels[i],22,\'end\');s+=rect(x0,y-10,length,20,\'#62657f\');s+=rect(x0,y-10,v*length,20,BLUE);\n            s+=circle(x,y,18,BLUE,{stroke:\'#ffffff\',\'stroke-width\':2,...mark(`${key} · ${labels[i]}\\n完成率 ${exactPct(values[i])}`,values[i],{\'data-category\':labels[i]})});\n            s+=txt(x+32,y+7,pct(values[i]),21,\'start\');\n        });svg.innerHTML=s;\n    });\n}\nmodes.forEach(el=>el.addEventListener(\'change\',updateOptions));select.addEventListener(\'change\',update);updateOptions();\n</script></body></html>'

payload=json.dumps(data,ensure_ascii=False,allow_nan=False).replace('<','\u003c')
output=HERE/(Path(__file__).stem+'.html')
output.write_text(PAGE.replace('__SOURCE_DATA__',payload),encoding='utf-8')
print(output)
